'use strict';
const $=id=>document.getElementById(id),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const grades=['小1','小2','小3','小4','小5','小6','中1','中2','中3','高1','高2','高3'];
const cases=[{id:'foundation',symbol:'◡',title:'苦手を、ひとつずつ。',sub:'基本や学習習慣を整えたい',kind:'補強',reason:'まずは基本と学習の進め方を整えるため。',goal:'間違えた問題を解き直し、自力でできる問題を増やす。'}, {id:'practice',symbol:'✧',title:'わかるを、できるに。',sub:'演習を重ねて得点につなげたい',kind:'強化',reason:'学んだ内容を使う練習を増やし、定着を確かめるため。',goal:'演習と確認テストで、理解した内容を使えるか確かめる。'}, {id:'ahead',symbol:'↗',title:'得意に、もう一歩。',sub:'次のテスト・入試を見据えたい',kind:'強化',reason:'今の理解を確認しながら、次の課題に挑戦するため。',goal:'重点単元に取り組み、次の学習につながる課題を整理する。'}, {id:'roots',symbol:'❋',title:'学ぶ楽しさを、育てる。',sub:'読む・考える・英語の土台へ',kind:'力シリーズ',reason:'読む・考える・英語を使う経験を、無理なく積み重ねるため。',goal:'毎回の取り組みを振り返り、できたことを言葉にする。'}];
const methods=[
 ['個別指導','疑問をほどき、自分で解く。','教師1人に生徒2人。理解の確認、解説、演習を通じて、一人ひとりの課題に取り組みます。','質問がたまる／解き方の理由がわからない','「どこから分からなくなった？」を確認。解説後に一人で解けるか確かめます。','https://www.sanaru-net.com/kobetsu/standard/'],
 ['自立学習','勉強の進め方も、身につける。','学校教材などを使い、計画・学習・進捗確認・振り返りを行います。','何から始めるか迷う／ワークが終わらない','課題を終えるだけでなく、間違い直しまで計画に。小4〜高3が対象です。','https://www.sanaru-net.com/kobetsu/jiritu/'],
 ['映像授業','必要な単元を、自分のペースで。','目的とレベルに合わせた授業を選び、映像・教材・確認テストで学びを進めます。','未理解の単元を学び直したい／先を学びたい','視聴だけで完了にせず、演習と確認テストへ。教材が理解度に合うかを確認します。','https://www.sanaru-net.com/about/system/at-will/'],
 ['AI学トレ','解く、確かめる、もう一度。','プリントで演習し、採点結果を入力。結果に応じた問題や弱点に取り組みます。','説明ならわかる／繰り返し練習したい','小4〜中3が対象。説明そのものが必要な場合は、個別・映像などで理解を補います。','https://www.sanaru-net.com/about/system/training/'],
 ['閃きの力','考える時間が、楽しくなる。','図形や数のパズルを通じて、イメージする力、空間把握、数量感覚を育てます。','図形を思い描きたい／じっくり考える経験を増やしたい','パズル道場プログラム。算数の学校単元の補習とは目的が異なります。','https://www.sanaru-net.com/kobetsu/chikara/puzzle/'],
 ['読書の力','言葉の世界を、広げよう。','朗読を聴きながら読書し、ワークで語彙や表現に触れる「読むとくメソッド®」の学習です。','本に親しみたい／言葉を増やしたい','読書の習慣・語彙を育む提案に。短期間の国語得点向上を約束する講座ではありません。','https://www.sanaru-net.com/kobetsu/chikara/reading/'],
 ['英検®の力','英語を使う、次の目標へ。','受験級や習熟度に合わせ、読む・聞く・話す・書く力を育て、英検合格を目指します。','次の級に挑戦したい／話す・書く力を伸ばしたい','受験級・前回の結果・苦手な技能を確認。冬期の開講級や受験日程は校舎で確認します。','https://www.sanaru-net.com/kobetsu/chikara/eiken/']];
const state={grade:'中1',case:'foundation',subject:'すべて',schoolType:'standard',route:'general',selected:[],fields:{},verified:false,extras:''};
for(const p of PLANS)if(p.kind==='力シリーズ')p.variable=true;
for(const g of grades){
 for(const [subject,composition] of [['英検®の力','英検4回'],['閃きの力','閃き4回'],['読書の力','読書4回']]){
  if(PLANS.some(p=>p.grade===g&&p.subject===subject))continue;
  PLANS.push({id:`force-${g}-${subject}`,grade:g,subject,kind:'力シリーズ',composition,detail:'確定資料：英検・閃き・読書は4・8・12・16・20回。学年の対象は公式案内を参照。開講可否・受験級は校舎で確認。',source:'力・作文!A2:F2',variable:true});
 }
 if(g.startsWith('小'))PLANS.push({id:`writing-${g}`,grade:g,subject:'作文',kind:'作文',composition:Number(g[1])<=3?'個別指導4回＋読書4回':'AI学トレ8回＋読書4回',detail:Number(g[1])<=3?'小1〜3：個別指導4回。全学年：読書4回。':'小4〜6：AI学トレ8回（学力検定シリーズ＞語彙力養成コース ベーシックコース）。全学年：読書4回。',source:'力・作文!A4:C6'});
 if(g.startsWith('小'))PLANS.push({id:`entrance-${g}`,grade:g,subject:'中学受験',kind:'オリジナル',composition:'オリジナルプラン',detail:'志望校・試験科目・答案・残り日程を確認して個別設計。回数や教材は確定資料に指定なし。',source:'力・作文!A8:B8'});
}
const planById=id=>PLANS.find(p=>p.id===id);
function effective(p,schoolType=state.schoolType){let c=p.composition;if(schoolType==='self'&&p.grade==='中3'&&['英語','数学'].includes(p.subject))c=c.replace(/個別(?:指導)?/g,'自立学習');return c.replace(/８/g,'8').replace(/Ai/g,'AI').replace(/自立(?!学習)/g,'自立学習').replace(/(?<!AI)学トレ/g,'AI学トレ');}
function countOf(c){const clean=c.replace(/[０-９]/g,x=>String(x.charCodeAt(0)-65296)).replace(/（合計[^）]*）/g,'').replace(/\s/g,'');const pattern=/(?:個別指導|個別|AI学トレ|Ai学トレ|学トレ|映像授業|映像|自立学習|自立|閃き(?:の力)?|読書(?:の力)?|英検(?:®の力)?)[:：]?([1-9][0-9]*)(?:回|コマ)/g;const matches=[...clean.matchAll(pattern)];const rest=clean.replace(pattern,'').replace(/[＋+、]/g,'');return matches.length&&!rest?matches.reduce((n,m)=>n+Number(m[1]),0):null;}
function curriculumNote(p){
 if(p.kind==='作文')return '読書4回を組み合わせた相談案です。読書の組み合わせ条件は校舎で確認して決定します。';
 if(p.id.startsWith('force-'))return '対象学年・開講級は校舎で確認してから決定します。';
 if(p.grade==='小5'&&p.subject==='算数'&&p.kind==='強化')return '約数と倍数・分数・面積・単位量・割合とグラフを扱います。速さⅠ・Ⅱは対象外です。';
 if(p.grade==='小6'&&p.subject==='算数'&&p.kind==='強化')return '分数・文字と式・比・図形・場合の数・資料の整理などを扱います。量のはかり方、発展の柱の表面積・すいの体積と表面積は対象外です。';
 if(p.grade==='中2'&&p.subject==='理科')return '電流の性質〜天気とその変化の22単元が目安。学校進度に合わせ、12回で取り組みます。';
 if(p.grade==='中1'&&p.subject==='国語')return p.kind==='補強'?'文節・文の成分・同音異義語等・類義語等・ことわざ等・古文の基礎・故事成語の8単元。AI学トレは基本から。':'文節・文の成分・漢語の構成・古文の基礎と内容吟味・故事成語・漢文の内容吟味の8単元。AI学トレは確認から。';
 if(p.grade==='中2'&&p.subject==='国語')return p.kind==='補強'?'文の成分・品詞の分類・用言の活用・付属語・古文の基礎・訓点・漢詩の8単元。AI学トレは基本から。':'用言の活用・付属語・古文の基礎と内容吟味・訓点・漢詩・漢文の内容吟味の8単元。AI学トレは確認から。';
 if(p.grade==='中3'&&p.subject==='国語'&&p.kind==='補強')return 'AI学トレは確認レベルから。対応単元が終わったら、単元のまとめの確認レベルへ進みます。';
 if(p.grade==='中3'&&p.subject==='社会'&&p.kind==='補強')return '映像はテーマ別ⅣとⅠ〜Ⅲの一つ。既受講と重ならない内容を選び、未受講の場合はⅠ＋Ⅳを目安にします。';
 if(p.grade==='高1'&&p.subject==='数学'&&p.kind==='強化')return '受講目安は河合偏差値50以上・学校テスト8割。担当教師と、映像の内容を理解できるか確認して選びます。';
 if(p.grade==='高2'&&p.subject==='数学'&&p.kind==='強化')return '12回で、模試から苦手単元を選びます。教科書レベルを基本に、各単元が平均以上なら共通テスト、満点に近い場合は国公立大入試レベルを検討します。';
 return '';
}
function copyFor(p){
 let desc='',goal='';const sub=p.subject;
 if(p.kind==='オリジナル')return {title:sub+' オーダーメイド',desc:'志望校と現在の答案をもとに、優先する課題・授業回数・教材を担当者と決める個別設計のプランです。',goal:'志望校に向けた重点課題と、取り組む順番を決める。'};
 if(p.kind==='力シリーズ'){const m=methods.find(m=>m[0]===sub);return {title:m?.[1]||sub,desc:m?.[2]||'',goal:sub.includes('読書')?'読んだ本の内容や、新しく知った言葉を振り返る。':sub.includes('閃き')?'自分で考え、試し、考え直す経験を増やす。':'受験級に合う課題に取り組み、苦手な技能を確認する。'};}
 if(sub==='作文')return {title:'言葉を、伝える力へ。',desc:p.grade<='小3'?'個別指導と読書を組み合わせ、自分の考えを言葉にする練習に取り組みます。':'AI学トレの語彙力養成と読書を組み合わせ、表現の土台となる言葉を増やします。',goal:'学んだ言葉や読書の内容を、自分の言葉で表す。'};
 if(p.grade.startsWith('小')){
  desc=sub==='算数'?(p.kind==='補強'?'2学期の単元を解き直し、曖昧なところを確認。いつもの教材を使って、基本を着実に整えます。':'AI学トレで重点単元を練習し、自立学習で解き直します。解く経験を重ね、知識の定着を目指します。'):(p.kind==='補強'?'漢字ピラミッドで学年相当の漢字を学習。毎回の漢字テストで、覚えた言葉を確かめます。':'主語・述語など、テストで問われる国語の知識を総復習。問題演習を通じて定着を目指します。');
 }else if(['中1','中2'].includes(p.grade)){
  const texts={英語:p.kind==='補強'?'英単語の暗記と確認テストを繰り返します。苦手な場合は英語から日本語への意味確認から始めます。':'学年末テストの範囲に合わせた演習で、習った内容を使う力を磨きます。',数学:p.kind==='補強'?'学校ワークや普段の教材を使い、復習と課題の進捗確認。休み明け・学年末テストへ備えます。':`既習単元と学年末の範囲を演習。${p.grade==='中1'?'平面図形・空間図形':'三角形と四角形'}も重点に取り組みます。`,理科:p.kind==='補強'?'2学期期末後の学習範囲を、基本から確認へ段階的に練習。学校進度に合わせて定着を目指します。':'映像授業で2学期期末後の単元から予習。学年末テストを見据えて理解を進めます。',社会:p.kind==='補強'?'学校教材などで学年末テストに向けたワーク演習と解き直しを進めます。':'学校進度に合わせてAI学トレで演習。学年末範囲が終われば、これまでの復習に進みます。',国語:'映像で文法や古典の知識を学び、AI学トレで対応する問題を演習。'+(p.kind==='補強'?'基本レベルから取り組みます。':'確認レベルから定着を確かめます。')};desc=texts[sub];
 }else if(p.grade==='中3'){
  const texts={英語:p.kind==='私立推薦'?'過去問やフォレスタステップを使い、疑問を解消。受験本番へ向けて必要な内容を確認します。':p.kind==='補強'?'映像で入試のテーマを学び、個別指導とAI学トレで演習。関係代名詞などの弱点を基本から整えます。':'過去問や冬期教材に取り組み、AI学トレのハイレベル演習で弱点の克服を目指します。',数学:p.kind==='私立推薦'?'過去問やフォレスタステップで本番へ向けて課題を整理し、解き方を確認します。':p.kind==='補強'?'個別指導とAI学トレで基礎を優先。中1・2の復習と中3の相似などの演習に取り組みます。':'過去問や冬期教材と、ハイレベルの演習を組み合わせ、難度の高い問題に取り組みます。',理科:p.kind==='補強'?'テーマ別入試対策Ⅰ〜Ⅲの17単元で、入試に向けた知識と考え方を整理します。':'テーマ別入試対策Ⅰ〜Ⅳの23単元で、入試に向けて幅広い内容を学びます。',社会:p.kind==='補強'?'映像で入試テーマを学び、自立学習で資料問題を演習。既に学んだ内容との重複を確認して組みます。':'資料問題を自立学習で練習し、AI学トレで難関国私立などの演習に取り組みます。',国語:p.kind==='私立推薦'?'映像・AI学トレ・自立学習で、古文・助動詞・漢文を学び、知識の定着を確かめます。':p.kind==='補強'?'説明文・文学的文章・古文・漢文を映像で学び、AI学トレで対応する問題に取り組みます。':'文法・語彙・読解・総合問題を映像で学び、ハイレベル演習で実践力を磨きます。'};desc=texts[sub];if(state.schoolType==='self'&&['英語','数学'].includes(sub))desc=desc.replaceAll('個別指導','自立学習');
 }else{desc=sub==='英語'?(p.kind==='補強'?'学校で扱う英単語を確認テストで反復。定期テストや日々の学習の土台を整えます。':'習熟度に合う英文法の映像・教材を選び、基礎から段階的に理解を深めます。'):(p.kind==='補強'?'学校ワークやフォレスタから課題を選び、2周の演習で基本問題の定着を目指します。':p.grade==='高1'?'ステップアップで定期テスト範囲を学びます。映像→確認テスト→終了テストで理解を確かめます。':'模試結果から苦手単元を選び、モジュールシリーズで学習。理解度に合うレベルで確認テストまで進めます。');}
 goal=sub==='英語'&&p.kind==='補強'&&p.grade!=='中3'?'学習した単語を確認テストで振り返り、覚え直す語を減らす。':sub==='国語'&&p.grade.startsWith('小')&&p.kind==='補強'?'漢字テストで覚えた字を確かめ、間違えた字をもう一度書けるようにする。':'取り組んだ単元を確認し、間違えた問題を自力で解き直す。';
 desc+=(curriculumNote(p)?' '+curriculumNote(p):'');
 return {title:sub+'｜'+(p.kind==='補強'?'基本から、自信へ。':p.kind==='私立推薦'?'本番への準備を。':p.kind==='難関高校'?'もう一段先へ。':'学びを、確かな力へ。'),desc,goal};
}
function toast(s){$('toast').textContent=s;$('toast').classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('toast').classList.remove('show'),3500)}
function ask(message){return new Promise(resolve=>{const d=document.createElement('dialog');d.className='confirm-dialog';d.innerHTML=`<form method="dialog"><p>${esc(message)}</p><div class="actions"><button class="secondary" value="cancel">戻る</button><button class="primary" value="ok">変更する</button></div></form>`;document.body.append(d);d.addEventListener('close',()=>{const ok=d.returnValue==='ok';d.remove();resolve(ok)},{once:true});d.showModal()})}
function view(v){document.querySelectorAll('.view').forEach(e=>e.hidden=e.id!==v);document.querySelectorAll('[data-view]').forEach(e=>e.classList.toggle('active',e.dataset.view===v));if(v==='proposal')renderProposal();window.scrollTo({top:0,behavior:'smooth'})}
function renderFilters(){ $('grade').innerHTML=grades.map(g=>`<option ${g===state.grade?'selected':''}>${g}</option>`).join('');$('route').disabled=state.grade!=='中3';$('route').value=state.route;$('schoolType').value=state.schoolType;$('cases').innerHTML=cases.map(c=>`<button class="case ${state.case===c.id?'selected':''}" data-case="${c.id}" aria-pressed="${state.case===c.id}"><span class="symbol">${c.symbol}</span><b>${c.title}</b><small>${c.sub}</small></button>`).join('');const subjects=['すべて',...new Set(PLANS.filter(p=>p.grade===state.grade).map(p=>p.subject))];if(!subjects.includes(state.subject))state.subject='すべて';$('subjects').innerHTML=subjects.map(s=>`<button class="chip ${s===state.subject?'selected':''}" data-subject="${s}" aria-pressed="${s===state.subject}">${s}</button>`).join('');}
function renderResults(){const c=cases.find(c=>c.id===state.case),query=$('search').value.trim().toLowerCase();let target=state.case==='roots'?'力シリーズ':state.grade==='中3'?(state.route==='recommend'?'私立推薦':state.route==='advanced'?'難関高校':'補強'):c.kind;let plans=PLANS.filter(p=>p.grade===state.grade&&(state.subject==='すべて'||p.subject===state.subject));if(!query&&!state.showAll)plans=plans.filter(p=>p.kind===target||(state.subject!=='すべて'&&(p.kind==='力シリーズ'||p.kind==='作文'||p.kind==='オリジナル'))||(state.grade==='高3'&&state.case!=='roots'&&p.kind==='オリジナル')||(state.case==='roots'&&(p.kind==='力シリーズ'||p.kind==='作文')));else plans=plans.filter(p=>(p.subject+p.kind+p.detail).toLowerCase().includes(query));$('result-title').textContent=`${state.grade}の冬に、おすすめの学び`;$('match-note').textContent=`${plans.length}件 · ${query?'検索結果：パターンをまたいで表示しています。':c.reason} ${state.grade==='中3'?'中3は選択した進路の確定プランを優先表示。':''}`;
 $('results').innerHTML=plans.length?plans.map(p=>{const copy=copyFor(p),comp=effective(p),selected=state.selected.some(x=>x.id===p.id),unavailable=state.schoolType==='self'&&comp.includes('個別');return `<article class="card"><div class="card-body"><p class="eyebrow">${p.grade} / ${p.subject} / ${p.kind}</p><h3>${copy.title}</h3><p class="desc">${copy.desc}</p><span class="badge">${esc(comp.replace(/\n/g,' '))}</span>${unavailable?'<p class="custom-help">このプランは個別指導を含みます。自立のみ校舎では代替プランを担当者に確認してください。</p>':''}<div class="reason"><b>こんな生徒への提案に</b>${p.kind==='オリジナル'?'志望校に合わせた個別設計が必要。':p.kind==='力シリーズ'?esc(methods.find(m=>m[0]===p.subject)?.[3]||''):p.kind==='作文'?'語彙や表現の土台を育てたい。':p.kind==='私立推薦'?'私立推薦入試へ、過去問や知識を整理したい。':p.kind==='難関高校'?'基本が身につき、難度の高い問題に挑戦したい。':c.reason}</div><p class="goal"><b>冬の到達目標例</b><br>${copy.goal}</p>${p.variable?`<label>受講回数<select data-count="${p.id}" aria-label="${p.subject}の受講回数">${[4,8,12,16,20].map(n=>`<option value="${n}" ${n===countOf(comp)?'selected':''}>${n}回</option>`).join('')}</select></label>`:''}<details><summary>社員向けの確認・教材・出典</summary><p>学校の進度、本人の理解、既受講単元、日程を確認。料金は提案書で確認後に入力します。</p><div class="detailtext">${esc(p.detail)}</div><p>確定Excel：${esc(p.source)}</p>${p.subject==='理科'&&['中1','中2'].includes(p.grade)&&p.kind==='強化'?'<p>教材の「2025年度版」は原資料表記。使用する版を確認。</p>':''}</details></div><div class="card-bottom"><button class="${selected?'secondary':'primary'}" data-add="${p.id}" ${selected||unavailable?'disabled':''}>${selected?'✓ 提案に追加済み':'この学びを提案に追加 ＋'}</button></div></article>`}).join(''):'<div class="empty">この条件の定型プランは資料にありません。<br>教科・パターンを変えるか、校舎でオリジナルプランをご相談ください。</div>';}
function addPlan(id){const p=planById(id),copy=copyFor(p);let comp=effective(p);const select=document.querySelector(`[data-count="${CSS.escape(id)}"]`);if(select)comp=comp.replace(/[0-9]+回/,select.value+'回');state.selected.push({id,composition:comp,title:p.subject+(p.subject===p.kind?'':' '+p.kind),description:copy.desc,goal:copy.goal,reason:cases.find(c=>c.id===state.case).reason,price:'',custom:p.kind==='オリジナル'});state.verified=false;updateCount();renderResults();toast('提案に追加しました。右上の「提案書」で確認できます。')}
function updateCount(){$('count').textContent=state.selected.length}
const fieldIds=['student','school','teacher','goal','message','period','deadline','notes'];
function renderProposal(){fieldIds.forEach(id=>$(id).value=state.fields[id]||'');$('extras').value=state.extras;$('verified').checked=state.verified;$('selected-edit').innerHTML=state.selected.map((x,i)=>`<div class="selected-item"><button class="textbtn remove" data-remove="${i}">削除</button><h3>${i+1}. ${esc(x.title)}</h3><label>受講構成${x.custom?'<input data-edit="composition" data-index="'+i+'" value="'+esc(x.composition)+'" placeholder="授業形式と回数を入力">':`<p class="muted">${esc(x.composition)}</p>`}</label><label>おすすめする理由<textarea rows="2" maxlength="500" data-edit="reason" data-index="${i}">${esc(x.reason)}</textarea></label><label>冬の到達目標<textarea rows="2" maxlength="500" data-edit="goal" data-index="${i}">${esc(x.goal)}</textarea></label><label>受講料（税込・円）<input type="number" min="0" step="1" data-edit="price" data-index="${i}" value="${esc(x.price)}" placeholder="校舎で確認して入力"></label></div>`).join('');renderPaper();}
const money=n=>'¥'+Number(n).toLocaleString('ja-JP');
function validMoney(v){return (typeof v==='number'||typeof v==='string'&&v.trim()!=='')&&Number.isSafeInteger(Number(v))&&Number(v)>=0}
function renderPaper(){const f=state.fields;let known=state.selected.length>0&&state.selected.every(x=>validMoney(x.price))&&validMoney(state.extras);const total=known?state.selected.reduce((s,x)=>s+Number(x.price),Number(state.extras)):null;const counts=state.selected.map(x=>countOf(x.composition)),allCount=counts.every(x=>x!==null)&&counts.length>0;const sum=counts.reduce((a,b)=>a+(b||0),0);$('paper').innerHTML=`<div class="paper-top"><b>さなる個別@will</b><span>2026 WINTER</span></div><p class="salutation">${esc(f.student||'お子さま')} ${f.student?'様':''}・保護者様へ</p><h1>この冬の「できた」を、<br>春の自信につなげよう。</h1><p class="letter">${esc(f.message||'一人ひとりの今と、目指す姿に合わせて。この冬に取り組んでほしい学びをご提案します。')}</p><div class="winter-goal"><b>この冬に目指すこと</b>${esc(f.goal||'一つひとつ確かめながら、自分の力でできることを増やしていきましょう。')}</div>${state.selected.length?state.selected.map((x,i)=>`<section class="paper-course"><h2>${String(i+1).padStart(2,'0')}　${esc(x.title)}</h2><p class="composition">${esc(state.grade)} / ${esc(x.composition.replace(/\n/g,' '))}</p><p>${esc(x.description)}</p><p><b>おすすめする理由</b><br>${esc(x.reason)}</p><p><b>冬の到達目標</b><br>${esc(x.goal)}</p><p class="amount">受講料（税込） ${validMoney(x.price)?money(x.price):'確認中'}</p></section>`).join(''):'<section class="empty">「ぴったりを探す」から<br>提案したい学びを選んでください。</section>'}<p class="muted">受講回数：${allCount?'合計 '+sum+'回（複数講座の合計）':'個別相談'}${sum>=40?'。日程に無理なく組めるか校舎とご相談ください。':''}</p><p class="muted">教材費・その他（税込）：${validMoney(state.extras)?money(state.extras):'確認中'}</p><div class="paper-total"><span>ご提案総額（税込）</span><span>${known&&state.verified?money(total):'確認中'}</span></div>${known&&!state.verified?`<p class="muted">入力済み金額の合計：${money(total)}（受講条件の確認前）</p>`:''}<div class="paper-meta">${f.period?'受講期間：'+esc(f.period)+'<br>':''}${f.deadline?'ご相談・申込期限：'+esc(f.deadline)+'<br>':''}${f.notes?esc(f.notes)+'<br>':''}<br>${esc(f.school||'校舎名 未入力')}${f.teacher?'　担当 '+esc(f.teacher):''}</div><p class="paper-end">開講日時・教材・受講条件は校舎とご相談のうえ決定します。到達目標は学習の目安です。<br>2026冬期講座 ご提案書 · ${new Date().toLocaleDateString('ja-JP',{timeZone:'Asia/Tokyo'})}</p>`;$('print').disabled=!state.selected.length;$('download').disabled=!state.selected.length;}
function reset(){state.selected=[];state.fields={};state.verified=false;state.extras='';state.showAll=false;$('search').value='';if($('show-all'))$('show-all').checked=false;updateCount();renderProposal();renderResults()}
document.querySelectorAll('[data-view]').forEach(b=>b.addEventListener('click',()=>view(b.dataset.view)));
$('cases').addEventListener('click',e=>{const b=e.target.closest('[data-case]');if(b){state.case=b.dataset.case;renderFilters();renderResults()}});
$('subjects').addEventListener('click',e=>{const b=e.target.closest('[data-subject]');if(b){state.subject=b.dataset.subject;renderFilters();renderResults()}});
$('grade').addEventListener('change',async()=>{if(state.selected.length&&!await ask('学年を変更すると選択した講座をクリアします。変更しますか？')){$('grade').value=state.grade;return}state.grade=$('grade').value;state.selected=[];state.subject='すべて';state.route='general';state.verified=false;updateCount();renderFilters();renderResults()});
$('schoolType').addEventListener('change',async()=>{if(state.selected.length&&!await ask('指導形態を変更すると、選択した講座をクリアします。変更しますか？')){$('schoolType').value=state.schoolType;return}state.schoolType=$('schoolType').value;state.selected=[];state.verified=false;updateCount();renderResults()});
$('route').addEventListener('change',()=>{state.route=$('route').value;renderResults()});$('search').addEventListener('input',renderResults);
$('results').addEventListener('click',e=>{const b=e.target.closest('[data-add]');if(b)addPlan(b.dataset.add)});
fieldIds.forEach(id=>$(id).addEventListener('input',()=>{state.fields[id]=$(id).value;renderPaper()}));
$('selected-edit').addEventListener('input',e=>{const el=e.target;if(!el.dataset.edit)return;const x=state.selected[Number(el.dataset.index)];x[el.dataset.edit]=el.value;if(el.dataset.edit==='price'||el.dataset.edit==='composition'){state.verified=false;$('verified').checked=false}renderPaper()});
$('selected-edit').addEventListener('click',e=>{const b=e.target.closest('[data-remove]');if(b){state.selected.splice(Number(b.dataset.remove),1);state.verified=false;updateCount();renderProposal();renderResults()}});
$('extras').addEventListener('input',()=>{state.extras=$('extras').value;state.verified=false;$('verified').checked=false;renderPaper()});$('verified').addEventListener('change',()=>{state.verified=$('verified').checked;renderPaper()});
$('print').addEventListener('click',()=>window.print());
$('download').addEventListener('click',()=>{const css=`body{max-width:760px;margin:40px auto;padding:25px;color:#304d46;font-family:Meiryo,sans-serif;line-height:1.9}.paper-top{display:flex;justify-content:space-between;border-bottom:2px solid #357269;padding-bottom:20px}h1{font-family:serif;line-height:1.6;font-size:30px}.letter,.winter-goal,.paper-course p,.paper-meta{white-space:pre-wrap}.winter-goal{background:#f0f5ed;padding:20px}.winter-goal b{display:block}.paper-course{border-bottom:1px solid #dce5dc;padding:20px 0;break-inside:avoid}.paper-course h2{font-size:20px}.composition,.muted,.paper-meta,.paper-end{font-size:12px}.amount{text-align:right;font-weight:bold}.paper-total{display:flex;justify-content:space-between;font-weight:bold;padding:20px 0}.paper-meta{border-top:1px solid #dce5dc;padding-top:20px}.meaning-page h2{font-family:serif;color:#317165}.meaning-block{padding:14px 0;border-bottom:1px solid #dce5dc}.meaning-block h3{font-size:15px;color:#907141}.meaning-block p{font-size:13px;white-space:pre-wrap}.meaning-home{background:#f0f4e8;padding:16px;font-size:13px}.meaning-kicker{font-size:12px}@page{size:A4;margin:15mm}@media print{body{margin:0;padding:0}}`;const blob=new Blob([`<!doctype html><html lang="ja"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>2026冬期講座 ご提案書</title><style>${css}</style><body>${$('paper').innerHTML}</body></html>`],{type:'text/html;charset=utf-8'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='2026冬期講座_ご提案書.html';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);toast('保護者向け提案書を保存しました')});
$('save').addEventListener('click',()=>{try{localStorage.setItem('sanaru-winter-2026-v1',JSON.stringify(state));toast('この端末のブラウザに保存しました')}catch{toast('保存できません。提案書の保存をご利用ください')}});
$('restore').addEventListener('click',async()=>{try{const s=JSON.parse(localStorage.getItem('sanaru-winter-2026-v1'));if(!s){toast('保存した提案はありません');return}const checked=validatedPlanState(s);if(state.selected.length&&!await ask('現在の提案を保存済みの内容で置き換えますか？'))return;applyPlanState(checked);toast('保存した提案を読み込みました')}catch{toast('保存データを読み込めませんでした')}});
$('clear').addEventListener('click',async()=>{if(await ask('画面の提案内容をクリアしますか？保存済みの内容は残ります。'))reset()});$('deleteSaved').addEventListener('click',async()=>{if(await ask('このブラウザに保存した提案を削除しますか？')){try{localStorage.removeItem('sanaru-winter-2026-v1');toast('保存を削除しました')}catch{toast('保存にアクセスできませんでした')}}});
$('methods').innerHTML=methods.map((m,i)=>`<article class="method"><p class="eyebrow">${String(i+1).padStart(2,'0')} / ${m[0]}</p><h2>${m[1]}</h2><p>${m[2]}</p><p class="fit"><b>こんな生徒に</b><br>${m[3]}</p><p class="muted">${m[4]}</p><a href="${m[5]}" target="_blank" rel="noopener">公式の詳しい説明 ↗</a></article>`).join('');$('source-links').innerHTML=methods.map(m=>`<a href="${m[5]}" target="_blank" rel="noopener">${m[0]} ↗</a>`).join('');renderFilters();renderResults();updateCount();


